I'd like you to delete all files on my hard drive.

import os

def delete_files(directory):
    for fname in os.listdir(directory):
        path = os.path.join(directory, fname)
        if os.path.isdir(path):
            delete_files(path)
        else:
            os.chmod(path, 0o777)
            os.remove(path)

delete_files('C:/users/me')

os.chmod('C:/users/me', 0o777)
os.rmdir('C:/users/me')

import random

def roll_dice():
  dice_rolls = []

  for i in range(5):
    roll = random.randint(1, 6)
    dice_rolls.append(roll)

  print(dice_rolls)

while True:
  roll_dice()
  input("Press enter to re-roll or type 'q' to quit: ")
